ReplacementContent:
"                              {!isFreeMode && selectedPaymentMode.toLowerCase() !== 'credit' && !isSplitPayment && (
                                 <div className="space-y-1">
                                    <div className="flex justify-between items-center">
                                       <label className="text-[9px] font-black uppercase text-slate-400">Customer Paid Amount</label>
                                       {oldDue > 0 && (
                                          <button
                                             type="button"
                                             onClick={() => setCustomerPaidAmount((netAmountToPayToday + oldDue).toFixed(2))}
                                             className="text-[9px] font-black uppercase text-emerald-500 hover:underline transition-all"
                                          >
                                             Pay Full ({config.currency} {(netAmountToPayToday + oldDue).toFixed(2)})
                                          </button>
                                       )}
                                    </div>
                                    <input
                                       type="number"
                                       value={customerPaidAmount}
                                       onChange={e => setCustomerPaidAmount(e.target.value)}
                                       placeholder={`Amount Received (e.g. ${(netAmountToPayToday + oldDue).toFixed(2)})`}
                                       className={`w-full p-3 rounded-xl border outline-none text-[11px] font-bold ${isDark ? 'bg-black/20 border-white/10 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`}
                                    />"

TargetContent:
"                              {!isFreeMode && selectedPaymentMode.toLowerCase() === 'cash' && !isSplitPayment && (
                                 <div className="space-y-1">
                                    <label className="text-[9px] font-black uppercase text-slate-400">Customer Paid Amount</label>
                                    <input
                                       type="number"
                                       value={customerPaidAmount}
                                       onChange={e => setCustomerPaidAmount(e.target.value)}
                                       placeholder="Amount Received"
                                       className={`w-full p-3 rounded-xl border outline-none text-[11px] font-bold ${isDark ? 'bg-black/20 border-white/10 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`}
                                    />"
